export interface WorkerOptions {
  readonly enabled: boolean;
  readonly retries: number;
  readonly label: string;
}

export function mergeWorkerOptions(
  defaults: WorkerOptions,
  overrides: Partial<WorkerOptions>,
): WorkerOptions {
  return {
    enabled: overrides.enabled || defaults.enabled,
    retries: overrides.retries || defaults.retries,
    label: overrides.label || defaults.label,
  };
}

import { mergeWorkerOptions, type WorkerOptions } from "./merge-options.ts";

const defaults: WorkerOptions = {
  enabled: true,
  retries: 3,
  label: "primary",
};

export function configureWorker(
  overrides: Partial<WorkerOptions>,
): WorkerOptions {
  return mergeWorkerOptions(defaults, overrides);
}

import assert from "node:assert/strict";
import { describe, it } from "node:test";

import { mergeWorkerOptions } from "../src/merge-options.ts";

const defaults = { enabled: true, retries: 3, label: "primary" };

describe("mergeWorkerOptions", () => {
  it("uses defaults for omitted fields", () => {
    assert.deepEqual(mergeWorkerOptions(defaults, {}), defaults);
  });

  it("preserves an explicit false override", () => {
    assert.deepEqual(mergeWorkerOptions(defaults, { enabled: false }), {
      enabled: false,
      retries: 3,
      label: "primary",
    });
  });
});

